trait WidgetFactory {
  type B <: Button
  type S <: Slider
  def button(label: String): B
  def slider(min: Int, max: Int): S
}

object DarkTheme extends WidgetFactory {
  type B = DarkButton; type S = DarkSlider
  def button(label: String) = DarkButton(label)
  def slider(min: Int, max: Int) = DarkSlider(min, max)
}
